Serie *retorna_preenchido(int *i)
{
    // Abrir o arquivo
    FILE *arquivo = fopen("streaming_db.csv", "r");
    if (arquivo == NULL)
    {
        perror("\nErro ao abrir o arquivo!\n");
        exit(1);
    }

    // Pular a linha de cabeçalho
    char vetor_guarda_linha[150];
    if (fgets(vetor_guarda_linha, 150, arquivo) == NULL) {
        fclose(arquivo);
        return NULL; // Arquivo vazio
