        pt = strtok(NULL, ",");
        vetor_series[*i].quantidade_de_temporada = atoi(pt);

        // Alocação dos episódios
        vetor_series[*i].quantidade_de_ep = (int *)malloc(vetor_series[*i].quantidade_de_temporada * sizeof(int));
        if (vetor_series[*i].quantidade_de_temporada > 0 && vetor_series[*i].quantidade_de_ep == NULL) {
             perror("Erro ao alocar episódios");
             // Lógica de limpeza...
             fclose(arquivo);
             exit(1);
        }

        // Leitura dos episódios (separados por ", ")
        for (int j = 0; j < vetor_series[*i].quantidade_de_temporada; j++)
        {
